function(ctx){window.__qiworkReadEvidence=function(root){
  if(!root)return {state:'unknown',confidence:'none'};
  var nodes=[root].concat(Array.from(root.querySelectorAll('*')));
  var values=['aria-pressed','aria-checked','data-selected','data-checked','data-active']
    .map(function(name){return root.getAttribute(name);})
    .filter(function(value){return value!==null;})
    .map(function(value){return String(value).toLowerCase();});
  var labels=nodes.map(function(el){
    return [el.innerText||'',el.getAttribute&&el.getAttribute('aria-label')||'',el.getAttribute&&el.getAttribute('title')||''].join(' ');
  }).join(' ').trim();
  var colors=[];
  nodes.forEach(function(el){
    var style=getComputedStyle(el);
    [style.color,style.fill,style.stroke].forEach(function(v){if(v)colors.push(v);});
  });
  var e2e=String(root.getAttribute('data-e2e-state')||'').toLowerCase();
  var attributeActive=window.__qiworkTokens.activeState.indexOf(e2e)>=0;
  var attributeInactive=window.__qiworkTokens.inactiveState.indexOf(e2e)>=0;
  var explicitTrue=values.some(function(v){return ['true','1','yes'].indexOf(v)>=0;});
  var explicitFalse=values.some(function(v){return ['false','0','no'].indexOf(v)>=0;});
  var activeText=window.__qiworkTokens.activeText.some(function(t){return t&&labels.indexOf(t)>=0;});
  var activeStyle=window.__qiworkTokens.activeStyle.some(function(token){
    return colors.some(function(color){return color.toLowerCase().indexOf(token.toLowerCase())>=0;});
  });
  var activeClass=nodes.some(function(el){
    return /(^|[-_\s])(active|selected|checked|liked|favorited|collected)([-_\s]|$)/i.test(String(el.className||''));
  });
  var highActive=attributeActive||explicitTrue||activeText||activeStyle;
  var highInactive=attributeInactive||explicitFalse;
  var conflict=highActive&&highInactive;
  var state=conflict?'unknown':highActive?'active':highInactive?'inactive':activeClass?'active':'unknown';
  var confidence=conflict?'none':(highActive||highInactive)?'high':activeClass?'low':'none';
  return {state:state,confidence:confidence,e2e:e2e,label:labels.slice(0,200)};
};

  window.__qiworkTokens={
    activeText:["已赞", "取消赞", "已点赞", "取消点赞"],
    activeStyle:["rgb(255, 44, 85)", "#ff2c55"],
    activeState:["video-player-is-digged"],
    inactiveState:["video-player-no-digged"]
  };
  var selectors=[["[data-e2e=\"video-player-digg\"]"]];
  var visible=function(el){
    if(!el)return false;
    if(!(el.offsetWidth||el.offsetHeight||el.getClientRects().length))return false;
    var style=getComputedStyle(el);
    return style.display!=='none'&&style.visibility!=='hidden'&&Number(style.opacity||1)>0;
  };
  Array.from(document.querySelectorAll('[data-qiwork-target]')).forEach(function(el){
    el.removeAttribute('data-qiwork-target');
  });
  var root=null;
  for(var i=0;i<selectors.length&&!root;i++){
    var nodes=document.querySelectorAll(selectors[i]);
    for(var j=0;j<nodes.length;j++){
      if(visible(nodes[j])){root=nodes[j];break;}
    }
  }
  var want=String(ctx.action||'like')==='like';
  if(!root){
    window.__qiworkInteract={kind:'like',found:false,state:'missing',confidence:'none',target:want,needed:false};
    return {kind:'like',found:false,state:'missing',confidence:'none',target:want,needed:false};
  }
  root.setAttribute('data-qiwork-target','1');
  var evidence=window.__qiworkReadEvidence(root);
  var needed=evidence.confidence==='high'&&(
    (want&&evidence.state==='inactive')||(!want&&evidence.state==='active')
  );
  window.__qiworkInteract={
    kind:'like',found:true,state:evidence.state,confidence:evidence.confidence,
    target:want,needed:needed,clicked:false
  };
  return {kind:'like',found:true,state:evidence.state,confidence:evidence.confidence,target:want,needed:needed};
}

