  var st=window.__qiworkInteract||{};
  var root=document.querySelector('[data-qiwork-target="1"]');
  var evidence=root?window.__qiworkReadEvidence(root):{state:'unknown',confidence:'none'};
  var expected=st.target?'active':'inactive';
  return {
    kind:'like',
    action:st.target?'activate':'deactivate',
    found:!!root,
    before:st.state||'',
    state:evidence.state,
    state_verified:evidence.confidence==='high'&&evidence.state===expected,
    clicked:!!st.needed
  };
